<div class="section-heading"><div><span>Transaction ledger</span><h2>Payment history</h2><p>Every recorded online and offline payment.</p></div></div><div class="portal-card table-wrap"><table><thead><tr><th>Date</th><th>Invoice</th><th>Method</th><th>Amount</th><th>Status</th><th>Transaction ID</th></tr></thead><tbody><?php foreach($payments as $row):?><tr><td><?=htmlspecialchars($row['payment_date'])?></td><td><?=htmlspecialchars($row['invoice_number'])?></td><td><?=htmlspecialchars(str_replace('_',' ',$row['method']))?></td><td>₹<?=number_format((float)$row['amount'],2)?></td><td><span class="status"><?=htmlspecialchars($row['status'])?></span></td><td><?=htmlspecialchars($row['transaction_id']??'—')?></td></tr><?php endforeach;?></tbody></table></div>
